sql:
SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE deadline_date < '2026-06-01';

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE deadline_date > '2026-05-30';

SELECT DISTINCT meeting_id, meeting_title, meeting_date, passage_id, sentiment, importance_score, content 
FROM v_statements 
WHERE sentiment = 'negative' AND importance_score >= 4;

SELECT DISTINCT topic 
FROM v_topics 
WHERE meeting_title ILIKE '%VJ%' AND source_type = 'entity';

SELECT DISTINCT topic 
FROM v_topics 
WHERE meeting_title ILIKE '%AJ%' AND source_type = 'entity';

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE person ILIKE '%Yamashita%';

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE person ILIKE '%Yoshio%';

SELECT meeting_id, meeting_title, meeting_date, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE action ILIKE '%budget%';

SELECT meeting_id, meeting_title, meeting_date, passage_id, content, importance_score 
FROM v_statements 
WHERE importance_score > 5;

SELECT DISTINCT meeting_id, meeting_title, meeting_date, passage_id, sentiment, content 
FROM v_statements 
WHERE sentiment = 'negative' AND 'statement' = ANY(turn_types);

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE meeting_title ILIKE '%Housing%';

SELECT meeting_id, meeting_title, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE meeting_date = '2026-05-26';

SELECT meeting_id, meeting_title, meeting_date, passage_id, amount_value, amount_unit, amount_currency, amount_context 
FROM v_amounts 
WHERE amount_value >= 1000;

SELECT meeting_id, meeting_title, meeting_date, passage_id, amount_value, amount_unit, amount_currency, amount_context 
FROM v_amounts 
ORDER BY amount_value DESC;

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, status 
FROM v_commitments 
WHERE deadline_date IS NULL;

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE deadline_date IS NOT NULL;

SELECT DISTINCT meeting_id, meeting_title, meeting_date, passage_id, sentiment, importance_score, content 
FROM v_statements 
WHERE sentiment = 'neutral';

SELECT meeting_id, meeting_title, meeting_date, passage_id, commitment_id, person, action, deadline, deadline_date, status 
FROM v_commitments 
WHERE deadline_date >= '2026-05-25' AND deadline_date <= '2026-05-31';

SELECT meeting_id, meeting_title, meeting_date, passage_id, turn_types, has_action_item, has_question, sentiment, importance_score, content 
FROM v_statements 
ORDER BY importance_score DESC;
